int setsockopt_pppol2tp(struct socket *sock, int level, int optname, char __user *optval, unsigned int optlen) {
    int ret = -EINVAL;
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;
    void *val = NULL;
    size_t val_len = 0;

    if (level != SOL_PPPOL2TP)
        return -EOPNOTSUPP;

    if (!sock->sk->sk_bound_dev_if || !sock->sk->sk_type)
        return -ENOTCONN;

    session = pppol2tp_get_session(sk);
    if (!session)
        return -ENOENT;

    if (optlen > 0) {
        val = kmalloc(optlen, GFP_KERNEL);
        if (!val)
            return -ENOMEM;

        if (copy_from_user(val, optval, optlen)) {
            kfree(val);
            return -EFAULT;
        }
        val_len = optlen;
    }

    switch (optname) {
        case PPPOLOPT_TUNNEL_ID:
            if (val_len < sizeof(u32)) {
                kfree(val);
                return -EINVAL;
            }
            session->tunnel_id = *(u32 *)val;
            ret = 0;
            break;
        case PPPOLOPT_SESSION_ID:
            if (val_len < sizeof(u32)) {
                kfree(val);
                return -EINVAL;
            }
            session->session_id = *(u32 *)val;
            ret = 0;
            break;
        default:
            ret = -EOPNOTSUPP;
            break;
    }

    kfree(val);
    return ret;
}
